* JSON -- JSON Explorer.
* Maps in this set:
*   JSONCONSOLE - The JSON Explorer Console.
*   JSONHELP    - Display the JSON Explorer help test.
*   JSONPRETTY  - Display Pretty Printed JSON.
*   METRICSDEMO - The JSON Demo to display Bricks metrics.
*   JSONTESTS   - Display the result of running the tests.

MAPSET JSON1L

MAP JSONCONSOLE SIZE 43x80
  FIELD           AT 0 ,0   LEN 18  PROT COLOR=YELLOW         "JSON Explorer"
  FIELD FIND_TEXT AT 0 ,28  LEN 15  PROT COLOR=WHITE
  FIELD           AT 0 ,20  LEN 7   PROT COLOR=CYAN    "Search:"
  INPUT SCROLL    AT 0 ,52  LEN 5   UNDERSCORE COLOR=WHITE
  STOP            AT 0 ,58
  FIELD           AT 0 ,44  LEN 7   PROT COLOR=CYAN    "Scroll:"
  FIELD CUR_PAGE  AT 0 ,64  LEN 5   PROT COLOR=WHITE
  FIELD           AT 0 ,58  LEN 5   PROT COLOR=CYAN    "Page:"
  FIELD PAGE_CNT  AT 0 ,74  LEN 4   PROT COLOR=WHITE
  FIELD           AT 0 ,70  LEN 4   PROT COLOR=CYAN    "Of:"

  FIELD JTYPE     AT 1 ,6   LEN 10  PROT COLOR=WHITE
  FIELD           AT 1 ,0   LEN 5   PROT COLOR=CYAN    "Type:"
  FIELD JPATH     AT 1 ,28  LEN 15    PROT COLOR=WHITE
