MAP METRICSDEMO SIZE 24x80
  FIELD           AT 0 ,0   LEN 26  PROT COLOR=BLUE           "JSON DEMO - Bricks Metrics"

  FIELD USERID    AT 0 ,48  LEN 6   PROT COLOR=CYAN
